import {scan,checklistMarkdown,calendar} from './core.js';
const $=id=>document.getElementById(id),key='deadlineguard-v1';let state={name:'',url:'',rules:'',items:[]},filter='All';
const message=t=>$('message').textContent=t;
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{message('Storage is unavailable or full. Export your checklist before leaving.');}}
function download(data,name,type){const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function render(){const active=state.rules.length>0;$('empty').hidden=active;$('result').hidden=!active;if(!active)return;const complete=state.items.filter(i=>i.done).length,reviewed=state.items.filter(i=>i.reviewed).length;$('progress').textContent=complete+' / '+state.items.length+' completed';$('review-count').textContent=(state.items.length-reviewed)+' need review';$('meter').value=state.items.length?100*complete/state.items.length:0;$('items').replaceChildren();
const visible=state.items.filter(i=>filter==='All'||i.category===filter);if(!visible.length){const p=document.createElement('p');p.textContent='No findings in this category. Review the original rules and add any missed requirements.';$('items').append(p);}
for(const item of visible){const wrap=document.createElement('article');wrap.className='item'+(item.done?' done':'');const top=document.createElement('div');top.className='item-top';const check=document.createElement('input');check.type='checkbox';check.id=item.id;check.checked=item.done;check.addEventListener('change',()=>{item.done=check.checked;save();render();});const body=document.createElement('div');const tag=document.createElement('div');tag.className='tag';tag.textContent=item.category;const label=document.createElement('label');label.htmlFor=item.id;label.textContent=item.text;body.append(tag,label);top.append(check,body);const details=document.createElement('details'),summary=document.createElement('summary'),quote=document.createElement('blockquote');summary.textContent='View source & confirm';quote.textContent=item.source;const review=document.createElement('label');review.className='review';const rc=document.createElement('input');rc.type='checkbox';rc.checked=item.reviewed;rc.addEventListener('change',()=>{item.reviewed=rc.checked;save();$('review-count').textContent=state.items.filter(i=>!i.reviewed).length+' need review';});review.append(rc,document.createTextNode('I checked this against the official rules'));details.append(summary,quote,review);wrap.append(top,details);$('items').append(wrap);}}
function hydrate(){for(const field of ['name','url','rules'])$(field).value=state[field];render();}
try{const stored=JSON.parse(localStorage.getItem(key));if(stored&&typeof stored.name==='string'&&typeof stored.rules==='string'&&typeof stored.url==='string'&&Array.isArray(stored.items)&&stored.items.every(i=>typeof i.text==='string'&&typeof i.source==='string'&&['Deadlines','Eligibility','Submission'].includes(i.category)))state=stored;}catch{message('Saved workspace could not be loaded. You can start a fresh scan.');}hydrate();
$('scan-form').addEventListener('submit',e=>{e.preventDefault();try{const items=scan($('rules').value);if(state.items.length&&!confirm('Replace your current checklist and completion progress?'))return;state={name:$('name').value.trim(),url:$('url').value.trim(),rules:$('rules').value,items};filter='All';document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));save();render();message(items.length?'Checklist created. Review each finding and check the original for omissions.':'No requirements recognized. Add them manually using the original rules.');}catch(err){message(err.message);}});
$('sample').addEventListener('click',()=>{$('name').value='Community Build Challenge · fictional sample';$('url').value='';$('rules').value='FICTIONAL SAMPLE — not official competition rules.\nSubmission deadline: October 26, 2026 at 5:00 pm EDT.\nParticipants must be at least 18 years old.\nParticipants must reside in an eligible country.\nProjects must include a public code repository.\nThe repository must contain setup instructions and an open source license.\nA demo video is required and should be less than three minutes.\nThe video must be publicly visible on YouTube or Vimeo.\nAll submission materials must be in English.\nProjects must perform at least one function end to end.';message('Fictional example loaded. Select Build my checklist to scan it.');});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();}));
$('add-form').addEventListener('submit',e=>{e.preventDefault();state.items.push({id:'manual-'+Date.now(),category:$('new-category').value,text:$('new-text').value.trim(),source:$('new-source').value.trim(),reviewed:false,done:false});save();render();$('add-form').reset();});
$('export').addEventListener('click',()=>download(checklistMarkdown(state),'deadlineguard-checklist.md','text/markdown'));
$('print').addEventListener('click',()=>window.print());
$('calendar-form').addEventListener('submit',e=>{e.preventDefault();try{download(calendar(state.name,$('date').value,$('time').value,$('offset').value),'deadlineguard-reminder.ics','text/calendar');message('Calendar file created. Import it into your calendar; no reminder has been scheduled by this app.');}catch(err){message(err.message);}});
$('reset').addEventListener('click',()=>{if(confirm('Clear this workspace? Export first if you want to keep a copy.')){state={name:'',url:'',rules:'',items:[]};try{localStorage.removeItem(key);}catch{}hydrate();message('Workspace cleared.');}});
